int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    static int a[100000];
    for (int i = 0; i < n; i++) {
        scanf("%d", &a[i]);
    }

    int maxRight = 0;   /* máximo das alturas à direita da posição atual */
    int invisible = 0;

    /* Percorre da frente (cadeira N) para o fundo (cadeira 1).
       O aluno i não é visto se existe j > i com a_j >= a_i,
       ou seja, se a_i <= máximo das alturas à sua direita. */
    for (int i = n - 1; i >= 0; i--) {
        if (a[i] <= maxRight) {
            invisible++;
        } else {
            maxRight = a[i];
        }
    }

    printf("%d\n", invisible);
    return 0;
}
